const listItems = $('Build Workflow List').all();
const idToName = {};
for (const it of listItems) { idToName[it.json.workflowId] = it.json.workflowName; }
const cutoff = Date.now() - 24 * 60 * 60 * 1000;
const out = [];
for (const item of $input.all()) {
  const ex = item.json;
  if (!ex || !ex.id) continue;
  const startedAt = ex.startedAt || ex.startedAtDate || ex.createdAt;
  if (startedAt) {
    const t = new Date(startedAt).getTime();
    if (!isNaN(t) && t < cutoff) continue;
  }
  const wfId = (ex.workflowId != null) ? String(ex.workflowId) : '';
  out.push({ json: {
    executionId: String(ex.id),
    workflowId: wfId,
    workflowName: idToName[wfId] || ex.workflowName || 'unknown',
  }});
}
return out;

const PRICES = {
  // Opus models (per 1M tokens)
  'claude-opus-4-0520': { input: 15, output: 75 },
  'claude-opus-4-1': { input: 15, output: 75 },
  'claude-opus-4-5': { input: 5, output: 25 },
  'claude-opus-4-6': { input: 15, output: 75 },
  'claude-opus-4-7': { input: 15, output: 75 },
  'claude-opus-4-8': { input: 15, output: 75 },

  // Sonnet models
  'claude-sonnet-4-0514': { input: 3, output: 15 },
  'claude-sonnet-4-20250514': { input: 3, output: 15 },
  'claude-sonnet-4-5': { input: 3, output: 15 },
  'claude-sonnet-4-6': { input: 3, output: 15 },

  // Haiku models
  'claude-haiku-4-5': { input: 1, output: 5 },

  // Fable / Opus 5
  'claude-fable-5': { input: 10, output: 50 },
  'claude-opus-5': { input: 5, output: 25 },
  'claude-sonnet-5': { input: 3, output: 15 },

  // OpenAI embeddings
  'text-embedding-3-small': { input: 0.02, output: 0.02 },
  'text-embedding-ada-002': { input: 0.10, output: 0.10 },
};

// Fuzzy matching fallback
function getPrice(model) {
  if (!model) return { input: 15, output: 75 }; // unknown = assume expensive
  const m = model.toLowerCase();
  if (PRICES[m]) return PRICES[m];
  if (m.includes('opus-5') || m.includes('opus-4-5')) return { input: 5, output: 25 };
  if (m.includes('opus')) return { input: 15, output: 75 };
  if (m.includes('sonnet')) return { input: 3, output: 15 };
  if (m.includes('haiku')) return { input: 1, output: 5 };
  if (m.includes('fable')) return { input: 10, output: 50 };
  if (m.includes('embedding')) return { input: 0.02, output: 0.02 };
  return { input: 15, output: 75 }; // fallback
}
const flatItems = $('Filter & Flatten').all();
const perWorkflow = {};
const perModel = {};
let grandCost = 0;
let grandExecutions = 0;
let grandTokens = 0;
const dataItems = $input.all();
for (let i = 0; i < dataItems.length; i++) {
  const item = dataItems[i].json || {};
  const meta = (flatItems[i] && flatItems[i].json) || {};
  const workflowId = meta.workflowId || (item.workflowId != null ? String(item.workflowId) : 'unknown');
  const workflowName = meta.workflowName || 'unknown';
  const runData = item && item.data && item.data.resultData && item.data.resultData.runData;
  let execCost = 0;
  let execTokens = 0;
  if (runData && typeof runData === 'object') {
    for (const nodeName of Object.keys(runData)) {
      const runs = runData[nodeName];
      if (!Array.isArray(runs)) continue;
      for (const run of runs) {
        const lm = run && run.data && run.data.ai_languageModel;
        if (!Array.isArray(lm)) continue;
        let modelName = 'unknown';
        try {
          const io = run.inputOverride && run.inputOverride.ai_languageModel;
          if (Array.isArray(io) && io[0] && io[0][0] && io[0][0].json && io[0][0].json.options && io[0][0].json.options.model) {
            modelName = io[0][0].json.options.model;
          }
        } catch (e) {}
        for (const outer of lm) {
          if (!Array.isArray(outer)) continue;
          for (const entry of outer) {
            const tu = entry && entry.json && entry.json.tokenUsage;
            if (!tu) continue;
            const promptTokens = Number(tu.promptTokens || 0);
            const completionTokens = Number(tu.completionTokens || 0);
            const p = getPrice(modelName);
            const cost = (promptTokens / 1e6) * p.input + (completionTokens / 1e6) * p.output;
            execCost += cost;
            execTokens += promptTokens + completionTokens;
            if (!perModel[modelName]) perModel[modelName] = { inputTokens: 0, outputTokens: 0, cost: 0 };
            perModel[modelName].inputTokens += promptTokens;
            perModel[modelName].outputTokens += completionTokens;
            perModel[modelName].cost += cost;
          }
        }
      }
    }
  }
  if (!perWorkflow[workflowId]) {
    perWorkflow[workflowId] = { workflowName, workflowId, totalCost: 0, executionCount: 0, totalTokens: 0 };
  }
  perWorkflow[workflowId].totalCost += execCost;
  perWorkflow[workflowId].executionCount += 1;
  perWorkflow[workflowId].totalTokens += execTokens;
  grandCost += execCost;
  grandExecutions += 1;
  grandTokens += execTokens;
}
const workflowsArr = Object.values(perWorkflow).map((w) => ({
  workflowId: w.workflowId,
  workflowName: w.workflowName,
  totalCost: w.totalCost,
  executionCount: w.executionCount,
  avgCostPerRun: w.executionCount > 0 ? w.totalCost / w.executionCount : 0,
  totalTokens: w.totalTokens,
}));
workflowsArr.sort((a, b) => b.totalCost - a.totalCost);
const modelsArr = Object.keys(perModel).map((m) => ({
  model: m,
  inputTokens: perModel[m].inputTokens,
  outputTokens: perModel[m].outputTokens,
  cost: perModel[m].cost,
}));
modelsArr.sort((a, b) => b.cost - a.cost);
return [{ json: {
  date: new Date().toISOString().slice(0, 10),
  grandTotalCost: grandCost,
  grandTotalExecutions: grandExecutions,
  grandTotalTokens: grandTokens,
  workflows: workflowsArr,
  models: modelsArr,
}}];

// Reads the single merged item: main summary fields (from Extract) + pipeline fields (from Aggregate)
const r = ($input.first() && $input.first().json) || {};
const date = r.date || new Date().toISOString().slice(0, 10);
const fmtCost = (n) => '$' + Number(n || 0).toFixed(4);
const fmtCost2 = (n) => '$' + Number(n || 0).toFixed(2);
const fmtK = (n) => (Number(n || 0) / 1000).toFixed(1) + 'K';
const workflows = Array.isArray(r.workflows) ? r.workflows : [];
const models = Array.isArray(r.models) ? r.models : [];
const grandExecutions = Number(r.grandTotalExecutions || 0);

// Pipeline data now arrives on the SAME merged item (combineByPosition)
const pipeCount = Number(r.pipelineSessionCount || 0);
const pipeTotal = Number(r.pipelineTotalCost || 0);
const pipeAvg = Number(r.pipelineAvgPerSession || 0);
const pipeWorkflows = (r.pipelineWorkflows && typeof r.pipelineWorkflows === 'object') ? r.pipelineWorkflows : {};
const PIPE_ORDER = ['SessionAnalysis', 'JobAnalysis', 'OpportunityAnalysis', 'SessionVectors', 'JobVectors'];

function pipelineLines() {
  const out = [];
  out.push('');
  if (pipeCount === 0) {
    out.push('\uD83D\uDCE6 Analysis Pipeline: No sessions processed in the last 24h');
    return out;
  }
  out.push('\uD83D\uDCE6 Analysis Pipeline: ' + pipeCount + ' sessions processed');
  out.push('Total: ' + fmtCost2(pipeTotal) + ' (avg ' + fmtCost2(pipeAvg) + '/session)');
  for (const name of PIPE_ORDER) {
    const w = pipeWorkflows[name];
    if (!w) continue;
    const cost = Number(w.cost || 0);
    const execs = Number(w.execCount || 0);
    if (execs > 0 && cost === 0) {
      out.push('\u2022 ' + name + ' \u2014 ' + execs + ' executions (embeddings \u2014 cost not captured)');
    } else {
      out.push('\u2022 ' + name + ' \u2014 ' + fmtCost2(cost) + ' (' + execs + ' executions)');
    }
  }
  return out;
}

const lines = [];
lines.push('\uD83E\uDDFE Daily AI Cost Report \u2014 ' + date);
lines.push('');
if (grandExecutions === 0) {
  lines.push('No AI executions in the last 24 hours.');
} else {
  lines.push('Total: ' + fmtCost(r.grandTotalCost) + ' across ' + grandExecutions + ' executions');
  lines.push('');
  lines.push('By Workflow:');
  const withRuns = workflows.filter((w) => Number(w.executionCount || 0) > 0);
  for (const w of withRuns) {
    lines.push('\u2022 ' + w.workflowName + ' \u2014 ' + fmtCost(w.totalCost) + ' (' + w.executionCount + ' runs, avg ' + fmtCost(w.avgCostPerRun) + '/run)');
  }
  lines.push('');
  lines.push('By Model:');
  if (models.length === 0) {
    lines.push('\u2022 (no token usage captured)');
  } else {
    for (const m of models) {
      lines.push('\u2022 ' + m.model + ' \u2014 ' + fmtCost(m.cost) + ' (' + fmtK(m.inputTokens) + ' input / ' + fmtK(m.outputTokens) + ' output tokens)');
    }
  }
}
lines.push(...pipelineLines());
lines.push('');
lines.push('\u26A0\uFE0F Gaps: Embedding token usage not captured via execution data.');
const message = lines.join('\n');
return [{ json: { message } }];

const listItems = $('Build Pipeline List').all();
const idToMeta = {};
for (const it of listItems) { idToMeta[it.json.workflowId] = it.json; }
const cutoff = Date.now() - 24 * 60 * 60 * 1000;
const out = [];
for (const item of $input.all()) {
  const ex = item.json;
  if (!ex || !ex.id) continue;
  const startedAt = ex.startedAt || ex.startedAtDate || ex.createdAt;
  if (startedAt) {
    const t = new Date(startedAt).getTime();
    if (!isNaN(t) && t < cutoff) continue;
  }
  const wfId = (ex.workflowId != null) ? String(ex.workflowId) : '';
  const meta = idToMeta[wfId] || {};
  out.push({ json: {
    executionId: String(ex.id),
    workflowId: wfId,
    workflowName: meta.workflowName || ex.workflowName || 'unknown',
    sessionIdField: meta.sessionIdField || 'id',
  }});
}
return out;

const PRICES = {
  // Opus models (per 1M tokens)
  'claude-opus-4-0520': { input: 15, output: 75 },
  'claude-opus-4-1': { input: 15, output: 75 },
  'claude-opus-4-5': { input: 5, output: 25 },
  'claude-opus-4-6': { input: 15, output: 75 },
  'claude-opus-4-7': { input: 15, output: 75 },
  'claude-opus-4-8': { input: 15, output: 75 },

  // Sonnet models
  'claude-sonnet-4-0514': { input: 3, output: 15 },
  'claude-sonnet-4-20250514': { input: 3, output: 15 },
  'claude-sonnet-4-5': { input: 3, output: 15 },
  'claude-sonnet-4-6': { input: 3, output: 15 },

  // Haiku models
  'claude-haiku-4-5': { input: 1, output: 5 },

  // Fable / Opus 5
  'claude-fable-5': { input: 10, output: 50 },
  'claude-opus-5': { input: 5, output: 25 },
  'claude-sonnet-5': { input: 3, output: 15 },

  // OpenAI embeddings
  'text-embedding-3-small': { input: 0.02, output: 0.02 },
  'text-embedding-ada-002': { input: 0.10, output: 0.10 },
};

// Fuzzy matching fallback
function getPrice(model) {
  if (!model) return { input: 15, output: 75 }; // unknown = assume expensive
  const m = model.toLowerCase();
  if (PRICES[m]) return PRICES[m];
  if (m.includes('opus-5') || m.includes('opus-4-5')) return { input: 5, output: 25 };
  if (m.includes('opus')) return { input: 15, output: 75 };
  if (m.includes('sonnet')) return { input: 3, output: 15 };
  if (m.includes('haiku')) return { input: 1, output: 5 };
  if (m.includes('fable')) return { input: 10, output: 50 };
  if (m.includes('embedding')) return { input: 0.02, output: 0.02 };
  return { input: 15, output: 75 }; // fallback
}

const flatItems = $('Flatten Pipeline').all();
const dataItems = $input.all();
const sessionMap = {}; // session_id -> { workflows: { name: { cost, tokens, execCount } }, totalCost, totalTokens }

for (let i = 0; i < dataItems.length; i++) {
  const item = (dataItems[i] && dataItems[i].json) || {};
  const meta = (flatItems[i] && flatItems[i].json) || {};
  const wfName = meta.workflowName || 'unknown';
  const sessionIdField = meta.sessionIdField || 'id';
  const runData = item && item.data && item.data.resultData && item.data.resultData.runData;
  if (!runData || typeof runData !== 'object') continue;

  // Extract session_id from sub_trigger node output
  let sessionId = null;
  const triggerData = runData['sub_trigger'];
  if (Array.isArray(triggerData) && triggerData[0] && triggerData[0].data && triggerData[0].data.main && triggerData[0].data.main[0] && triggerData[0].data.main[0][0] && triggerData[0].data.main[0][0].json) {
    sessionId = triggerData[0].data.main[0][0].json[sessionIdField];
  }
  if (!sessionId) sessionId = 'unknown';

  // Walk all nodes for token usage (proven lm/outer/entry shape)
  let execCost = 0;
  let execTokens = 0;
  for (const nodeName of Object.keys(runData)) {
    const runs = runData[nodeName];
    if (!Array.isArray(runs)) continue;
    for (const run of runs) {
      const lm = run && run.data && run.data.ai_languageModel;
      if (!Array.isArray(lm)) continue;
      let modelName = 'unknown';
      try {
        const io = run.inputOverride && run.inputOverride.ai_languageModel;
        if (Array.isArray(io) && io[0] && io[0][0] && io[0][0].json && io[0][0].json.options && io[0][0].json.options.model) {
          modelName = io[0][0].json.options.model;
        }
      } catch (e) {}
      for (const outer of lm) {
        if (!Array.isArray(outer)) continue;
        for (const entry of outer) {
          const tu = entry && entry.json && entry.json.tokenUsage;
          if (!tu) continue;
          const promptTokens = Number(tu.promptTokens || 0);
          const completionTokens = Number(tu.completionTokens || 0);
          const p = getPrice(modelName);
          const cost = (promptTokens / 1e6) * p.input + (completionTokens / 1e6) * p.output;
          execCost += cost;
          execTokens += promptTokens + completionTokens;
        }
      }
    }
  }

  if (!sessionMap[sessionId]) {
    sessionMap[sessionId] = { workflows: {}, totalCost: 0, totalTokens: 0 };
  }
  sessionMap[sessionId].totalCost += execCost;
  sessionMap[sessionId].totalTokens += execTokens;
  if (!sessionMap[sessionId].workflows[wfName]) {
    sessionMap[sessionId].workflows[wfName] = { cost: 0, tokens: 0, execCount: 0 };
  }
  sessionMap[sessionId].workflows[wfName].cost += execCost;
  sessionMap[sessionId].workflows[wfName].tokens += execTokens;
  sessionMap[sessionId].workflows[wfName].execCount += 1;
}

const sessions = Object.entries(sessionMap).filter(([id]) => id !== 'unknown');
const totalPipelineCost = sessions.reduce((sum, [, s]) => sum + s.totalCost, 0);
const avgPerSession = sessions.length > 0 ? totalPipelineCost / sessions.length : 0;

const wfTotals = {};
for (const [, session] of sessions) {
  for (const [wfName, wfData] of Object.entries(session.workflows)) {
    if (!wfTotals[wfName]) wfTotals[wfName] = { cost: 0, tokens: 0, execCount: 0 };
    wfTotals[wfName].cost += wfData.cost;
    wfTotals[wfName].tokens += wfData.tokens;
    wfTotals[wfName].execCount += wfData.execCount;
  }
}

return [{
  json: {
    pipelineSessionCount: sessions.length,
    pipelineTotalCost: totalPipelineCost,
    pipelineAvgPerSession: avgPerSession,
    pipelineWorkflows: wfTotals,
    pipelineSessions: Object.fromEntries(sessions.map(([id, data]) => [id, { cost: data.totalCost, tokens: data.totalTokens }])),
  }
}];
